9	/// ## What it does
10	/// Checks for class variable names that follow the `mixedCase` convention.
11	///
12	/// ## Why is this bad?
13	/// [PEP 8] recommends that variable names should be lower case and separated
14	/// by underscores (also known as `snake_case`).
15	///
16	/// > Function names should be lowercase, with words separated by underscores
17	/// > as necessary to improve readability.
18	/// >
19	/// > Variable names follow the same convention as function names.
20	/// >
21	/// > mixedCase is allowed only in contexts where that’s already the
22	/// > prevailing style (e.g. threading.py), to retain backwards compatibility.
23	///
24	/// ## Example
25	/// ```python
26	/// class MyClass:
27	///     myVariable = "hello"
28	///     another_variable = "world"
29	/// ```
30	///
31	/// Use instead:
32	/// ```python
33	/// class MyClass:
34	///     my_variable = "hello"
35	///     another_variable = "world"
36	/// ```
37	///
38	/// ## Options
39	/// - `lint.pep8-naming.ignore-names`
40	/// - `lint.pep8-naming.extend-ignore-names`
41	///
42	/// [PEP 8]: https://peps.python.org/pep-0008/#function-and-method-arguments
43	#[derive(ViolationMetadata)]
44	#[violation_metadata(stable_since = "v0.0.89")]
45	pub(crate) struct MixedCaseVariableInClassScope {
46	    name: String,
47	}
