58	pub(crate) fn mixed_case_variable_in_class_scope(
59	    checker: &Checker,
60	    expr: &Expr,
61	    name: &str,
62	    class_def: &ast::StmtClassDef,
63	) {
64	    if !helpers::is_mixed_case(name) {
65	        return;
66	    }
67	
68	    let parent = checker.semantic().current_statement();
69	
70	    if helpers::is_named_tuple_assignment(parent, checker.semantic())
71	        || helpers::is_typed_dict_class(class_def, checker.semantic())
72	    {
73	        return;
74	    }
75	
76	    if checker.settings().pep8_naming.ignore_names.matches(name) {
77	        return;
78	    }
79	
80	    checker.report_diagnostic(
81	        MixedCaseVariableInClassScope {
82	            name: name.to_string(),
83	        },
84	        expr.range(),
